// spots_base() FX.cpp:2913
function spotsBase(S, threshold) {
	if (S.len <= 1) return fb(S);
	if (!S.check2) S.fill(S.col[1]);
	const maxZones = S.len >> 2;
	const zones = 1 + ((S.intensity * maxZones) >> 8);
	const zoneLen = Math.floor(S.len / zones);
	const offset = (S.len - zones * zoneLen) >> 1;
	for (let z = 0; z < zones; z++) {
		const pos = offset + z * zoneLen;
		for (let i = 0; i < zoneLen; i++) {
			const wave = triwave16(Math.floor((i * 0xFFFF) / zoneLen));
			if (wave > threshold) {
				const index = pos + i;
				const s = Math.floor((wave - threshold) * 255 / (0xFFFF - threshold));
				S.setPixelColor(index, color_blend(S.color_from_palette(index, true, PSW(S), 0), S.col[1], (255 - s) & 0xFF));
			}
		}
	}
}
