// mode_glitter() FX.cpp:3392
FXS.add("Glitter", function(S) {
	if (!S.check2) {
		let counter = 0;
		if (S.speed != 0) counter = (Math.imul(S.now, (S.speed >> 3) + 1) & 0xFFFF) >> 8;
		const noWrap = paletteBlend == 2 || (paletteBlend == 0 && S.speed == 0);
		for (let i = 0; i < S.len; i++) {
			let colorIndex = (Math.floor(i * 255 / S.len) - counter) | 0; // unsigned in C: same bits
			if (noWrap) colorIndex = map(colorIndex, 0, 255, 0, 240); // long maths (negative stays negative)
			S.setPixelColor(i, S.color_from_palette(colorIndex & 0xFFFF, false, true, 255));
		}
	}
	glitterBase(S, S.intensity, S.col[2] ? S.col[2] : ULTRAWHITE);
});
