// mode_starburst() FX.cpp:3613 (compiled with WLED_PS_DONT_REPLACE_FX; struct particle {color, birth, last, vel, pos, fragment[10]})
FXS.add("Fireworks Starburst", function(S, E) {
	if (S.len <= 1) return fb(S);
	const STARBURST_MAX_FRAG = 10;
	let maxData = 2048; // FAIR_DATA_PER_SEG (ESP32 without PSRAM)
	const segs = S.getActiveSegmentsNum();
	if (segs <= (S.getMaxSegments() >> 1)) maxData *= 2;
	if (segs <= (S.getMaxSegments() >> 2)) maxData *= 2;
	const maxStars = Math.floor(maxData / 60); // sizeof(star)
	const numStars = Math.min(1 + (S.len >> 3), maxStars);
	const stars = E.s.st || (E.s.st = arr(numStars, () => ({color: 0, birth: 0, last: 0, vel: 0, pos: 0, fragment: new Array(STARBURST_MAX_FRAG).fill(0)})));
	const it = S.now >>> 0;
	const maxSpeed = 375, particleIgnition = 250, particleFadeTime = 1500;
	for (let j = 0; j < numStars; j++) {
		const st = stars[j];
		if (hw_random8(144 - (S.speed >> 1)) == 0 && st.birth == 0) {
			const startPos = hw_random16(S.len - 1);
			const multiplier = hw_random8() / 255;
			st.color = S.color_wheel(hw_random8()) & 0xFFFFFF; // CRGB drops W
			st.pos = startPos;
			st.vel = maxSpeed * hw_random8() / 255 * multiplier;
			st.birth = it;
			st.last = it;
			const num = hw_random8(3, 6 + (S.intensity >> 5));
			for (let i = 0; i < STARBURST_MAX_FRAG; i++) st.fragment[i] = i < num ? startPos : -1;
		}
	}
	if (!S.check2) S.fill(S.col[1]);
	for (let j = 0; j < numStars; j++) {
		const st = stars[j];
		if (st.birth != 0) {
			const dt = ((it - st.last) >>> 0) / 1000;
			for (let i = 0; i < STARBURST_MAX_FRAG; i++) {
				const v = i >> 1;
				if (st.fragment[i] > 0) st.fragment[i] += st.vel * dt * v / 3;
			}
			st.last = it;
			st.vel -= 3 * st.vel * dt;
		}
		let c = st.color;
		let fade = 0;
		let age = (it - st.birth) >>> 0;
		if (age < particleIgnition) {
			c = color_blend(WHITE, c, Math.trunc(254.5 * (age / particleIgnition))) & 0xFFFFFF;
		} else if (age > particleIgnition + particleFadeTime) {
			fade = 1;
			st.birth = 0;
			c = S.col[1] & 0xFFFFFF;
		} else {
			age -= particleIgnition;
			fade = age / particleFadeTime;
			c = color_blend(c, S.col[1], Math.trunc(254.5 * fade)) & 0xFFFFFF;
		}
		const particleSize = (1 - fade) * 2;
		for (let index = 0; index < STARBURST_MAX_FRAG * 2; index++) {
			const mirrored = index & 1;
			const i = index >> 1;
			if (st.fragment[i] > 0) {
				let loc = st.fragment[i];
				if (mirrored) loc -= (loc - st.pos) * 2;
				const start = Math.trunc(loc - particleSize) >>> 0; // float -> unsigned: negative values wrap (not drawn)
				let end = Math.trunc(loc + particleSize) >>> 0;
				if (start == end) end = (end + 1) >>> 0;
				if (end > S.len) end = S.len;
				for (let p = start; p < end; p++) S.setPixelColor(p, c);
			}
		}
	}
});
